// Temporary Unix-only Git shim support to unblock Windows native CI.
// Revisit after Windows support is defined; see the RFC temporary platform policy.
#![cfg(unix)]

//! Regression (::26 R1 second follow-up): a generated file (lockfile) that
//! the import ADDS through the opaque whole-content fast path and a later
//! commit MODIFIES must import with exact content fidelity.
//!
//! Before the fix, the modify ran a per-line diff against the file's single
//! whole-content branch. The diff's line numbers have no vertices in that
//! shape, the staged render came out truncated (Cargo.lock at 3,050 of
//! 89,750 bytes on a real repository), and the staged synthesis verification
//! refused the commit:
//!
//! ```text
//! partial import failed after 4 landed commit(s): staged synthesis
//! verification failed for ...: staged path 'Cargo.lock' renders 3050
//! byte(s) but the commit tree expects 89750 byte(s)
//! ```
//!
//! The fix routes a generated-file modify with bound branches through the
//! sentinel whole-file replace (delete all alive vertices, insert the full
//! content fresh, CRDT ops tombstone the bound branches).

use std::fs;
use std::path::Path;
use std::process::{Command, Output};

const ATOMIC_BIN: &str = env!("CARGO_BIN_EXE_atomic");

fn atomic(root: &Path, home: &Path, args: &[&str]) -> Output {
    Command::new(ATOMIC_BIN)
        .args(args)
        .current_dir(root)
        .env("HOME", home)
        .env("ATOMIC_HOME", home.join(".atomic"))
        .output()
        .expect("run atomic")
}

fn atomic_ok(root: &Path, home: &Path, args: &[&str]) {
    let output = atomic(root, home, args);
    assert!(
        output.status.success(),
        "atomic {args:?} failed:\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
}

fn git(root: &Path, args: &[&str]) {
    let output = Command::new("git")
        .args(args)
        .current_dir(root)
        .env("GIT_AUTHOR_NAME", "Generated Modify Tests")
        .env("GIT_AUTHOR_EMAIL", "generated-modify@example.com")
        .env("GIT_COMMITTER_NAME", "Generated Modify Tests")
        .env("GIT_COMMITTER_EMAIL", "generated-modify@example.com")
        .output()
        .expect("run git");
    assert!(
        output.status.success(),
        "git {args:?} failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
}

/// A deterministic multi-package lockfile. `packages` drives both the line
/// count and the byte count. `bump_from` rewrites the versions of every
/// package at or after that index, so the follow-up commit produces
/// IN-PLACE replace hunks scattered mid-file — the shape that corrupted the
/// staged render (the real Cargo.lock diff replaced lines ~1210-1220 across
/// 14 hunks while the graph held the file as one whole-content vertex).
fn lockfile(packages: usize, bump_from: usize) -> Vec<u8> {
    let mut content = String::from("# This file is automatically @generated by Cargo.\n");
    content.push_str("version = 3\n\n");
    for package in 0..packages {
        let major = if package >= bump_from { 2 } else { 1 };
        content.push_str(&format!(
            "[[package]]\nname = \"dep-{package}\"\nversion = \"{major}.{}.0\"\nsource = \"registry+https://github.com/rust-lang/crates.io-index\"\nchecksum = \"aaaaaaaa{package:04}bbbbbbbb{package:04}cccccccc{package:04}dddddddd{package:04}\"\ndependencies = [\n \"dep-{}\",\n]\n\n",
            package % 10,
            package.saturating_sub(1)
        ));
    }
    content.into_bytes()
}

#[test]
fn git_import_records_a_modified_generated_file_with_exact_content() {
    let root = tempfile::tempdir().unwrap().keep();
    let home = tempfile::tempdir().unwrap().keep();

    git(&root, &["init", "-q", "-b", "main"]);
    fs::write(
        root.join("Cargo.toml"),
        b"[package]\nname = \"app\"\nversion = \"0.1.0\"\n",
    )
    .unwrap();
    let initial_lock = lockfile(40, usize::MAX);
    fs::write(root.join("Cargo.lock"), &initial_lock).unwrap();
    git(&root, &["add", "."]);
    git(&root, &["commit", "-q", "-m", "initial with lockfile"]);

    // The follow-up commit bumps versions of every package past index 20
    // (in-place mid-file replaces) and adds packages at the end: a
    // multi-hunk, size-growing modification of an opaque generated file.
    let bumped_lock = lockfile(120, 20);
    assert!(bumped_lock.len() > initial_lock.len() * 2);
    fs::write(root.join("Cargo.lock"), &bumped_lock).unwrap();
    git(&root, &["add", "."]);
    git(&root, &["commit", "-q", "-m", "bump lockfile dependencies"]);

    atomic_ok(&root, &home, &["git", "import", "--no-vault"]);

    let repo = atomic_repository::Repository::open(&root).unwrap();
    let rendered = repo
        .get_file_content("Cargo.lock")
        .unwrap()
        .expect("Cargo.lock must be present after import");
    assert_eq!(
        rendered, bumped_lock,
        "the imported Cargo.lock must render the exact commit-tree bytes"
    );

    // The untouched tracked file must be unaffected by the replace.
    let toml = repo
        .get_file_content("Cargo.toml")
        .unwrap()
        .expect("Cargo.toml must be present after import");
    assert_eq!(
        toml,
        b"[package]\nname = \"app\"\nversion = \"0.1.0\"\n".to_vec()
    );
}

#[test]
fn git_import_records_the_real_helpers_history_with_exact_content() {
    // The exact `atomic-cli/src/commands/push/helpers.rs` states from the
    // atomicdotdev/atomic repository whose import failed at the deletion
    // commit: added at the initial commit (18,227 bytes), untouched through
    // three commits, modified by a +239-line insertion (26,964 bytes), then
    // "AI Cleanup" deleted 70 scattered banner lines (23,819 bytes). The
    // import failed with "staged path
    // 'atomic-cli/src/commands/push/helpers.rs' renders 27472 byte(s) but
    // the commit tree expects 23819 byte(s)".
    let c1 = include_bytes!("../fixtures/helpers_c1.rs");
    let c5 = include_bytes!("../fixtures/helpers_c5.rs");
    let c6 = include_bytes!("../fixtures/helpers_c6.rs");

    let root = tempfile::tempdir().unwrap().keep();
    let home = tempfile::tempdir().unwrap().keep();

    git(&root, &["init", "-q", "-b", "main"]);
    fs::write(root.join("src.rs"), c1).unwrap();
    fs::write(root.join("other.txt"), b"other\n").unwrap();
    git(&root, &["add", "."]);
    git(&root, &["commit", "-q", "-m", "initial"]);

    // The insertion commit ("working performance improvements", +239/−0).
    fs::write(root.join("src.rs"), c5).unwrap();
    git(&root, &["add", "."]);
    git(
        &root,
        &["commit", "-q", "-m", "working performance improvements"],
    );

    // The deletion commit ("AI Cleanup", +0/−70).
    fs::write(root.join("src.rs"), c6).unwrap();
    git(&root, &["add", "."]);
    git(&root, &["commit", "-q", "-m", "AI Cleanup"]);

    atomic_ok(&root, &home, &["git", "import", "--no-vault"]);

    let repo = atomic_repository::Repository::open(&root).unwrap();
    let rendered = repo
        .get_file_content("src.rs")
        .unwrap()
        .expect("src.rs must be present after import");
    assert_eq!(
        rendered,
        c6.to_vec(),
        "the imported src.rs must render the exact commit-tree bytes after the real pure-deletion modify"
    );
    let other = repo.get_file_content("other.txt").unwrap().unwrap();
    assert_eq!(other, b"other\n".to_vec());
}
